'use strict';
const {crops,goods,animals,recipes,buildings,crafts,quests,fresh,migrate,act}=Farm;
const KEY='teplaya-ferma-v1';let s=fresh(),selected='wheat',selectedWorkshop='mill',storageOK=true,openedPanel=null;
try{const raw=localStorage.getItem(KEY);if(raw){const restored=migrate(JSON.parse(raw));if(restored)s=restored;else storageOK=false;}}catch{storageOK=false;}
const $=id=>document.getElementById(id);let toastTimer;
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));}catch{toast('Браузер не сохраняет прогресс. Не закрывай страницу, чтобы его не потерять.');}}
function run(a){if(FarmPlatform.paused)return;const previous=a.type==='demolish'?s.durability[a.id]??FarmWorld.removableById[a.id]?.maxHP:null;const message=act(s,a);if(a.type==='demolish'&&(message.startsWith('Началась разборка')||(s.durability[a.id]??(s.removedObjects.includes(a.id)?0:previous))!==previous))FarmMap.pulse(a.id);toast(message);save();render();}
const seconds=t=>Math.max(0,Math.ceil((t-Date.now())/1000));
function render(){
renderProduction();renderQuest();renderCleanup();FarmMap.render(s);$('coins').textContent=s.coins;$('level').textContent=1+Math.floor(s.xp/50);$('xp').textContent=`${s.xp%50} / 50 опыта`;$('xp-fill').style.width=(s.xp%50)*2+'%';
$('seeds').innerHTML=Object.entries(crops).map(([k,c])=>`<button class="seed ${selected===k?'active':''}" data-seed="${k}" aria-pressed="${selected===k}" ${s.barn?'':'disabled'}><canvas data-art="${k}" width="72" height="58" aria-hidden="true"></canvas>${c.name}<small>${c.cost} 🪙 · ${c.time/1000} с</small></button>`).join('');
$('inventory').innerHTML=Object.entries(goods).map(([k,g])=>`<span class="stock" title="${g.name}">${g.icon}<b>${s.inventory[k]}</b><button data-sell="${k}" aria-label="Продать: ${g.name}" ${s.inventory[k]&&s.barn?'':'disabled'}>Продать</button></span>`).join('');
$('orders').innerHTML=s.orders.map((r,i)=>{const d=recipes[r],can=s.barn&&Object.entries(d.need).every(([k,v])=>s.inventory[k]>=v);return `<div class="order"><div class="order-head"><span class="avatar">${d.face}</span><div>${d.who}<div class="order-reward">${d.reward} 🪙 · ${d.xp} опыта</div></div></div><div class="order-body"><span>${Object.entries(d.need).map(([k,v])=>`${goods[k].icon} ${s.inventory[k]}/${v}`).join(' &nbsp; ')}</span><button data-order="${i}" ${can?'':'disabled'}>Доставить</button></div></div>`;}).join('');
$('animals').innerHTML=Object.entries(animals).map(([k,d])=>{const r=s.animals[k],built=s.buildings[d.building],ready=r!==null&&r<=Date.now();return `<div class="animal"><span>${d.icon}</span><div>${d.name}<small>${!built?'Сначала построй здание':r===null?'Сырьё: '+goods[d.food].icon+' ×2':ready?'Готово: '+goods[d.product].icon+' ×2':'Будет готово через '+seconds(r)+' с'}</small></div><button data-animal="${k}" ${!s.barn||!built||r!==null&&!ready?'disabled':''}>${r===null?'Запустить':ready?'Забрать':seconds(r)+' с'}</button></div>`;}).join('');
FarmArt.decorate();const price=Farm.plotPrice(s);$('expand').disabled=!s.barn;$('place-plot').disabled=!s.barn;$('harvest-all').disabled=!s.barn;$('expand').textContent='Поставить грядку · '+price+' 🪙';$('plot-tool-price').textContent='Грядка · '+price;
$('barn-warning').hidden=s.barn;
}
function switchTab(name){if(name&&FarmMap.placing)endPlacement();if(name&&FarmMap.demolishing)endDemolition();openedPanel=name;$('drawer').hidden=!name;document.querySelectorAll('[data-pane]').forEach(el=>el.hidden=el.dataset.pane!==name);document.querySelectorAll('[data-tab]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.tab===name)));}
function selectWorkshop(id){selectedWorkshop=id;renderProduction();document.querySelectorAll('[data-workshop-select]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.workshopSelect===id)));}
function harvestAll(){if(!s.barn){toast('Сначала восстанови амбар');return;}let count=0;for(let i=0;i<s.plots.length;i++)if(s.plots[i]&&s.plots[i].ready<=Date.now()){act(s,{type:'plot',i});count++;}if(count){save();render();toast('Собрано грядок: '+count+' 🌾');}else toast('Пока нет созревших грядок');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||FarmPlatform.paused)return;
if(b.dataset.mapAction){if(FarmMap.placing)return;const id=b.dataset.mapId;switch(b.dataset.mapAction){case'demolition':FarmMap.selectDemolition(id);break;case'plot':run({type:'plot',i:Number(id),crop:selected});break;case'tree':run({type:'tree',i:Number(id)});break;case'facility':switchTab('animals');break;case'workshop':selectWorkshop(id);switchTab('workshops');break;case'inventory':case'expand':switchTab('inventory');break;}return;}
if(b.dataset.tab){switchTab(openedPanel===b.dataset.tab?null:b.dataset.tab);return;}
if(b.dataset.workshopSelect){selectWorkshop(b.dataset.workshopSelect);return;}
if(b.dataset.build){beginBuildingPlacement(b.dataset.build);return;}if(b.dataset.craft)run({type:'craft',id:b.dataset.craft});if(b.dataset.collect)run({type:'collect',id:b.dataset.collect});if(b.id==='quest-claim')run({type:'quest'});if(b.dataset.sell)run({type:'sell',item:b.dataset.sell});if(b.dataset.restore)run({type:'restore',id:b.dataset.restore});if(b.dataset.repair)run({type:'repair',id:b.dataset.repair});if(b.dataset.seed){if(FarmMap.placing)endPlacement();if(FarmMap.demolishing)endDemolition();selected=b.dataset.seed;render();$('hint').textContent=crops[selected].icon+' '+crops[selected].name+': нажми на пустую грядку';}if(b.dataset.order!==undefined)run({type:'order',i:Number(b.dataset.order)});if(b.dataset.animal)run({type:'animal',id:b.dataset.animal});});
function beginPlacement(){if(FarmPlatform.paused)return;if(FarmMap.demolishing)endDemolition();switchTab(null);FarmMap.startPlacement();$('place-plot').setAttribute('aria-pressed','true');$('hint').textContent='Выбери клетку → «Поставить» · перетаскивание карты работает · Esc — отмена';}
function beginBuildingPlacement(id){if(FarmPlatform.paused||!buildings[id])return;if(FarmWorld.structureActive(s,id)){toast('Это здание уже есть или строится');return;}if(s.demolition[id]){toast('Сначала дождись конца разборки');return;}if(id!=='barn'&&!s.barn){toast('Сначала восстанови амбар');return;}if(1+Math.floor(s.xp/50)<buildings[id].level){toast('Нужен уровень '+buildings[id].level);return;}if(s.coins<buildings[id].cost){toast('Не хватает монет: нужно '+buildings[id].cost);return;}if(FarmMap.demolishing)endDemolition();switchTab(null);FarmMap.startPlacement(id);$('hint').textContent='🏗️ '+buildings[id].name+': выбери место · Esc — отмена';}
function endPlacement(){FarmMap.stopPlacement();$('place-plot').setAttribute('aria-pressed','false');$('hint').textContent='Перетаскивай карту · колёсико — масштаб';}
function beginDemolition(){if(FarmPlatform.paused)return;if(FarmMap.placing)endPlacement();switchTab(null);FarmMap.startDemolition();$('demolish-tool').setAttribute('aria-pressed','true');$('hint').textContent='🪓 Выбери объект · нажми «Ударить» · Esc — отмена';}
function endDemolition(){FarmMap.stopDemolition();$('demolish-tool').setAttribute('aria-pressed','false');$('hint').textContent='Перетаскивай карту · колёсико — масштаб';}
document.addEventListener('farm-demolition-change',event=>{const info=event.detail;$('demolition-bar').hidden=!info.active;$('demolition-title').textContent=info.name?info.name+(info.building?' · здание':' · '+info.hp+'/'+info.maxHP+' ♥'):'Разборка территории';$('demolition-status').textContent=info.name?(info.building?'Разборка займёт время. Нажми «Разобрать»':'Ещё ударов: '+info.hp+' · повторно коснись объекта или нажми кнопку'):'Выбери на карте куст, дерево, здание, цветник или забор';$('demolition-hit').textContent=info.building?'🪓 Разобрать':'🔨 Ударить';$('demolition-hit').disabled=!info.id;});
document.addEventListener('farm-demolition-hit',event=>run({type:'demolish',id:event.detail.id}));
document.addEventListener('farm-placement-change',event=>{const info=event.detail;$('placement-bar').hidden=!info.active;$('placement-price').textContent=(info.building?buildings[info.building].name+' · '+buildings[info.building].time/1000+' с':'Новая грядка')+' · '+info.price+' 🪙';$('placement-status').textContent=info.reason;$('confirm-placement').textContent=info.building?'Строить':'Поставить';$('confirm-placement').disabled=!info.ok;});
$('place-plot').onclick=()=>FarmMap.placing?endPlacement():beginPlacement();$('cancel-placement').onclick=endPlacement;
$('demolish-tool').onclick=()=>FarmMap.demolishing?endDemolition():beginDemolition();$('cancel-demolition').onclick=endDemolition;
$('demolition-hit').onclick=()=>{const info=FarmMap.demolition;if(info.id)run({type:'demolish',id:info.id});};
$('demolition-list').onclick=()=>switchTab('cleanup');
$('confirm-placement').onclick=()=>{if(FarmPlatform.paused)return;const info=FarmMap.placement;if(!info.active||!info.ok){toast(info.reason);return;}run(info.building?{type:'buildAt',id:info.building,c:info.c,r:info.r}:{type:'placePlot',c:info.c,r:info.r});if(info.building)endPlacement();};
$('close-panel').onclick=()=>switchTab(null);$('expand').onclick=beginPlacement;$('harvest-all').onclick=()=>{if(!FarmPlatform.paused)harvestAll();};$('zoom-in').onclick=()=>{if(!FarmPlatform.paused)FarmMap.zoomBy(1.15);};$('zoom-out').onclick=()=>{if(!FarmPlatform.paused)FarmMap.zoomBy(1/1.15);};$('camera-reset').onclick=()=>{if(!FarmPlatform.paused)FarmMap.reset();};
$('help').onclick=()=>{if(FarmPlatform.paused)return;FarmPlatform.pause('guide');$('guide').showModal();};$('guide').addEventListener('close',()=>FarmPlatform.resume('guide'));$('close-guide').onclick=()=>$('guide').close();
$('reset').onclick=()=>{if(FarmPlatform.paused)return;FarmPlatform.pause('confirm');if(confirm('Начать заново? Текущий прогресс будет удалён.')){endPlacement();endDemolition();switchTab(null);s=fresh();save();render();toast('Новая история начинается 🌱');}FarmPlatform.resume('confirm');};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!FarmPlatform.paused){if(FarmMap.placing)endPlacement();else if(FarmMap.demolishing)endDemolition();else if(openedPanel)switchTab(null);}});
$('motion-toggle').checked=FarmMap.motion;$('motion-toggle').onchange=e=>FarmMap.setMotion(e.target.checked);
setInterval(()=>{if(FarmPlatform.paused)return;if(Farm.advance(s)){save();render();}else if(Object.values(s.construction).some(Boolean)||Object.values(s.demolition).some(Boolean))renderProduction();Object.entries(animals).forEach(([k,d])=>{const r=s.animals[k];if(r!==null){const b=document.querySelector(`[data-animal="${k}"]`),ready=r<=Date.now();if(!b)return;b.disabled=!s.barn||!s.buildings[d.building]||!ready;b.textContent=ready?'Забрать':seconds(r)+' с';b.previousElementSibling.querySelector('small').textContent=ready?'Готово: '+goods[d.product].icon+' ×2':'Будет готово через '+seconds(r)+' с';}});document.querySelectorAll('[data-collect]').forEach(b=>{const j=s.jobs[b.dataset.collect];if(j){b.disabled=!s.barn||j.ready>Date.now();b.textContent=j.ready>Date.now()?seconds(j.ready)+' с':'Забрать';}});},500);
function ingredients(need){return Object.entries(need).map(([k,v])=>`${goods[k].icon} ${s.inventory[k]}/${v}`).join(' · ');}
function renderQuest(){const q=quests[s.quest];$('quest').innerHTML=q?`<div class="quest-icon">✦</div><div><small>ИСТОРИЯ ФЕРМЫ · ${s.quest+1}/${quests.length}</small><h2>${q.name}</h2><p>${q.text} · ${Math.min(s.stats[q.key],q.target)}/${q.target}</p></div><button id="quest-claim" ${s.barn&&s.stats[q.key]>=q.target?'':'disabled'}>+${q.reward} 🪙</button>`:'<div class="quest-icon">🏆</div><div><h2>Настоящий хозяин!</h2><p>Первые задания выполнены!</p></div>';}
function renderProduction(){ $('production').innerHTML=Object.entries(buildings).map(([k,b])=>{
 const j=s.jobs[k],built=k==='barn'?s.barn:s.buildings[k],underConstruction=s.construction[k],underDemolition=s.demolition[k],available=s.coins>=b.cost&&1+Math.floor(s.xp/50)>=b.level&&(k==='barn'||s.barn);
 const status=underConstruction?`<div class="work-status">🏗️ Строится · ${seconds(underConstruction.ready)} с<div class="progress-track"><i style="width:${Math.min(100,100*(Date.now()-underConstruction.started)/(underConstruction.ready-underConstruction.started))}%"></i></div></div>`:underDemolition?`<div class="work-status">💨 Разбирается · ${seconds(underDemolition.ready)} с<div class="progress-track"><i style="width:${Math.min(100,100*(Date.now()-underDemolition.started)/(underDemolition.ready-underDemolition.started))}%"></i></div></div>`:null;
 const body=status||(!built?`<button data-build="${k}" ${available?'':'disabled'}>Выбрать место · ${b.cost} 🪙 · ${b.time/1000} с${1+Math.floor(s.xp/50)<b.level?' · ур. '+b.level:''}</button>`:k==='barn'?'<div class="work-status">✅ Амбар работает. Все хозяйственные действия доступны.</div>':(k==='coop'||k==='cowshed')?'<div class="work-status">✅ Здание работает. Производство — в разделе «Хозяйства».</div>':j?`<div class="job"><span>${goods[crafts[j.craft].product].icon} ${goods[crafts[j.craft].product].name}</span><button data-collect="${k}" ${!s.barn||j.ready>Date.now()?'disabled':''}>${j.ready>Date.now()?seconds(j.ready)+' с':'Забрать'}</button></div>`:`<div class="craft-list">${Object.entries(crafts).filter(([,c])=>c.building===k).map(([id,c])=>`<div><span>${goods[c.product].icon} ${goods[c.product].name}<small>${ingredients(c.need)} · ${c.time/1000} с</small></span><button data-craft="${id}" ${s.barn&&Object.entries(c.need).every(([n,v])=>s.inventory[n]>=v)?'':'disabled'}>Готовить</button></div>`).join('')}</div>`);
 return `<article data-workshop="${k}" ${selectedWorkshop!==k?'hidden':''} class="building"><div class="building-head"><span>${b.icon}</span><div><h3>${b.name}</h3><p>${b.description}</p></div></div>${body}</article>`;
 }).join('');}
function renderCleanup(){const removed=FarmWorld.removables.filter(o=>!FarmWorld.structureById[o.id]&&s.removedObjects.includes(o.uid)),damaged=FarmWorld.removables.filter(o=>s.durability[o.uid]);const list=$('cleanup-list');list.innerHTML=removed.map(o=>`<div class="cleanup-item"><span>🪵 ${o.name}<small>Убрано с карты</small></span><button data-restore="${o.uid}">Вернуть · ${o.restoreCost} 🪙</button></div>`).join('')+damaged.map(o=>`<div class="cleanup-item"><span>🔨 ${o.name}<small>Прочность ${s.durability[o.uid]}/${o.maxHP}</small></span><button data-repair="${o.uid}">Ремонт · ${(o.maxHP-s.durability[o.uid])*2} 🪙</button></div>`).join('')||'<p class="muted">Пока ничего не разобрано и не повреждено.</p>';}
if(Farm.advance(s))save();render();FarmMap.ready.then(()=>{FarmArt.decorate();return FarmPlatform.init();}).then(()=>{if(!storageOK)toast('Старое сохранение недоступно. Открыта новая ферма.');}).catch(error=>{$('boot').innerHTML='<div><h2>Не загрузились изображения</h2><p>Перезагрузи страницу, чтобы повторить.</p><button onclick="location.reload()">Повторить</button></div>';console.error(error);});
